1	// QEMU TCG plugin: drains architectural state and exits when the guest
2	// executes the ROI enter marker `slti x0, x0, 0x5A0` (a HINT NOP). Shares
3	// hybrid/insn_match.h and hybrid/state_abi.h with the vsim side.
4	
5	#include "hybrid/handoff_site.h"
6	#include "hybrid/insn_match.h"
7	#include "hybrid/reg_names.h"
8	#include "hybrid/state_abi.h"
9	#include "hybrid/v_drain_policy.h"
10	#include "hybrid/write_mask.h"
11	
12	#include <qemu-plugin.h>
13	
14	#include <glib.h>
15	
16	#include <fcntl.h>
17	#include <inttypes.h>
18	#include <stddef.h>
19	#include <stdint.h>
20	#include <stdio.h>
21	#include <stdlib.h>
22	#include <string.h>
23	#include <unistd.h>
24	#include <limits.h>
25	
26	QEMU_PLUGIN_EXPORT int qemu_plugin_version = QEMU_PLUGIN_VERSION;
27	
28	typedef struct {
29	    struct qemu_plugin_register *gpr[32];
30	    struct qemu_plugin_register *fpr[32];
31	    struct qemu_plugin_register *fcsr;  // L20: frm[7:5] | fflags[4:0]
32	    struct qemu_plugin_register *pc;
33	    struct qemu_plugin_register *priv;  // L6: gdbstub virtual feature
34	
35	    // M-mode CSRs as exposed by QEMU's gdbstub csr feature.
36	    struct qemu_plugin_register *mstatus;
37	    struct qemu_plugin_register *mepc;
38	    struct qemu_plugin_register *mtvec;
39	    struct qemu_plugin_register *mcause;
40	    struct qemu_plugin_register *mtval;
41	    struct qemu_plugin_register *mscratch;
42	    struct qemu_plugin_register *medeleg;
43	    struct qemu_plugin_register *mideleg;
44	    struct qemu_plugin_register *mip;
45	    struct qemu_plugin_register *mie;
46	    struct qemu_plugin_register *mcycle;
47	    struct qemu_plugin_register *minstret;
48	    struct qemu_plugin_register *satp;
49	
50	    // Andes custom machine setup CSRs (crt0 writes these at boot). mcache_ctl
51	    // enables the L1 caches; without transporting it the cycle engine resumes
52	    // with caches off. Absent on non-Andes stubs -> NULL handle -> drains 0.
53	    struct qemu_plugin_register *mcache_ctl;
54	    struct qemu_plugin_register *mmisc_ctl;
55	
56	    // Andes V5 CSR block (v3). HYBRID_ANDES_CSR_LIST is the shared source of
57	    // truth; a NULL handle (non-Andes stub) drains 0 -> tolerant no-op.
58	#define HYBRID_ANDES_FIELD(field, addr, name) \
59	    struct qemu_plugin_register *andes_##field;
60	    HYBRID_ANDES_CSR_LIST(HYBRID_ANDES_FIELD)
61	#undef HYBRID_ANDES_FIELD
62	    struct qemu_plugin_register *pmacfg[HYBRID_PMA_CFG_NUM];
63	    struct qemu_plugin_register *pmaaddr[HYBRID_PMA_ADDR_NUM];
64	
65	    // M-ext CSR block (v4). Same shared X-macro; a NULL handle (the stub's
66	    // gdbstub does not advertise this CSR for the paired cpu) drains 0.
67	#define HYBRID_M_EXT_FIELD(field, addr, name) \
68	    struct qemu_plugin_register *m_ext_##field;
69	    HYBRID_M_EXT_CSR_LIST(HYBRID_M_EXT_FIELD)
70	#undef HYBRID_M_EXT_FIELD
71	
72	    struct qemu_plugin_register *pmpcfg[HYBRID_PMP_CFG_NUM];
73	    struct qemu_plugin_register *pmpaddr[HYBRID_PMP_ADDR_NUM];
74	
75	    struct qemu_plugin_register *vstart;
76	    struct qemu_plugin_register *vxsat;
77	    struct qemu_plugin_register *vxrm;
78	    struct qemu_plugin_register *vcsr;
79	    struct qemu_plugin_register *vtype;
80	    struct qemu_plugin_register *vl;
81	    struct qemu_plugin_register *vlenb;
82	    struct qemu_plugin_register *vreg[32];
83	} VcpuRegs;
84	
85	static struct qemu_plugin_scoreboard *vcpu_state;
86	static char *outfile_path;
87	
88	// PC-trigger mode: when enter_pc_arg is non-zero (set via plugin arg
89	// `enter_pc=0x...`), the CSR-insn matcher is bypassed entirely and the
90	// drain callback is registered only for instructions whose vaddr equals
91	// enter_pc_arg. The kind reported on the drain is HYBRID_HANDOFF_ENTER
92	// (entry into vsim), matching marker-mode enter-marker semantics.
93	static uint64_t enter_pc_arg;
94	static int pc_mode;
95	
96	// Oracle exit-drain mode (verify_oracle F1): when exit_marker_mode or
97	// exit_pc_mode is set (plugin args `exit_marker=1` / `exit_pc=0x...`), a
98	// pure-QEMU run produces the differential verifier's reference state. Every
99	// insn gets an exec callback: the tick ARMS on the
100	// ROI exit boundary (EXIT marker match, or vaddr == exit_pc) and DRAINS on
101	// the next callback. Exec callbacks fire before their insn executes, so the
102	// armed drain captures "after the boundary insn retired" -- exactly vsim's
103	// exit-drain record (DPC = next insn to execute) -- and reports that next
104	// insn's vaddr as pc, correct even when the boundary insn branches.
105	// Exclusive with the other trigger modes: the oracle run never hands off.
106	//
107	// drain_pc=0x... (optional modifier): drain at the first post-arm tick whose
108	// vaddr equals drain_pc, instead of the very next tick. The differential
109	// harness passes vsim's actual drained pc here: vsim's DMI halt lands a
110	// variable 0-3 insns past the trigger (the core keeps retiring while the
111	// haltreq propagates), and the two states only compare equal when both
112	// sides sample the SAME architectural point. If vsim's pc is never reached
113	// (a real control-flow divergence), the oracle never drains and QEMU runs
114	// to completion -- the caller sees exit != 200.
115	static uint64_t exit_pc_arg;
116	static int      exit_pc_mode;
117	static int      exit_marker_mode;
118	static uint64_t drain_pc_arg;
119	static int      drain_pc_set;
120	// v5: L2C MMIO register base. DS220 24.2 maps the AE350 L2C block at 0xE0500000;
121	// overridable via `l2c_base=0x...` for a platform with a relocated block.
122	static uint64_t l2c_base_arg = 0xE0500000ull;
123	
124	// LM transport (F1): hart-0 local-memory slave-port windows (AE350 memmap).
125	// When ilm_size/dlm_size/hvm_size are non-zero the drain also captures that
126	// many bytes of ILM/DLM/HVM CONTENT into raw sidecar files
127	// "<outfile>.ilm"/".dlm"/".hvm", for the vsim leg's --ilm/--dlm/--hvm
128	// backdoor load. The LM slave-port aperture is used (never the hart-local
129	// view: its ILM base 0x0 is also DRAM 0x0); HVM has only the one aperture
130	// (plain RAM at hvm_base, no enable bit). Size 0 (the default) = the paired
131	// engine has no such memory -> nothing read, no file written.
132	static uint64_t ilm_base_arg = 0xA0000000ull;
133	static uint64_t dlm_base_arg = 0xA0200000ull;
134	static uint64_t hvm_base_arg = 0x90000000ull;
135	static uint64_t ilm_size_arg;
136	static uint64_t dlm_size_arg;
137	static uint64_t hvm_size_arg;
138	static volatile int oracle_armed;
139	
140	// v6: which mask-governed config CSRs the guest has WRITTEN so far
141	// (hybrid/write_mask.h slot numbering). Marked by per-insn exec callbacks that
142	// are registered ONLY on instructions whose translate-time decode says "writes
143	// a governed CSR" -- steady-state code carries no instrumentation. Single-hart
144	// flow (like the rest of the handoff); atomics keep a future SMP guest safe.
145	static uint64_t csr_write_mask[2];
146	
147	static void on_csr_write(unsigned int vcpu_idx, void *udata)
148	{
149	    (void) vcpu_idx;
150	    const unsigned slot = (unsigned) (uintptr_t) udata;
151	    __atomic_fetch_or(&csr_write_mask[slot >> 6],
152	                      (uint64_t) 1 << (slot & 63u), __ATOMIC_RELAXED);
153	}
154	
155	static struct qemu_plugin_register *find_reg(GArray *regs, const char *name)
156	{
157	    for (guint i = 0; i < regs->len; i++) {
158	        qemu_plugin_reg_descriptor *rd =
159	            &g_array_index(regs, qemu_plugin_reg_descriptor, i);
160	        if (g_ascii_strcasecmp(rd->name, name) == 0) {
161	            return rd->handle;
162	        }
163	    }
164	    return NULL;
165	}
166	
167	// Lazily resolves register handles. The plugin's vcpu_init runs before
168	// QEMU has registered the dynamic gdb coprocessors (FPU, virtual, csr,
169	// vector), so qemu_plugin_get_registers() returns only the 33 core CPU
170	// regs at that moment. By the time the entry trigger fires, all dynamic
171	// features are registered and a fresh call returns the full list.
172	static void resolve_handles(VcpuRegs *v)
173	{
174	    g_autoptr(GArray) regs = qemu_plugin_get_registers();
175	    for (int i = 0; i < 32; i++) {
176	        v->gpr[i] = find_reg(regs, hybrid_gpr_names[i]);
177	        v->fpr[i] = find_reg(regs, hybrid_fpr_names[i]);
178	    }
179	    v->fcsr = find_reg(regs, "fcsr");
180	    v->pc = find_reg(regs, "pc");
181	    v->priv = find_reg(regs, "priv");
182	
183	    v->mstatus  = find_reg(regs, "mstatus");
184	    v->mepc     = find_reg(regs, "mepc");
185	    v->mtvec    = find_reg(regs, "mtvec");
186	    v->mcause   = find_reg(regs, "mcause");
187	    v->mtval    = find_reg(regs, "mtval");
188	    v->mscratch = find_reg(regs, "mscratch");
189	    v->medeleg  = find_reg(regs, "medeleg");
190	    v->mideleg  = find_reg(regs, "mideleg");
191	    v->mip      = find_reg(regs, "mip");
192	    v->mie      = find_reg(regs, "mie");
193	    v->mcycle   = find_reg(regs, "mcycle");
194	    v->minstret = find_reg(regs, "minstret");
195	    v->satp     = find_reg(regs, "satp");
196	
197	    v->mcache_ctl = find_reg(regs, "mcache_ctl");
198	    v->mmisc_ctl  = find_reg(regs, "mmisc_ctl");
199	
200	    char buf[16];
201	
202	    // Andes V5 CSR block (v3): resolve by gdb mnemonic from the shared X-macro.
203	#define HYBRID_ANDES_FIELD(field, addr, name) v->andes_##field = find_reg(regs, name);
204	    HYBRID_ANDES_CSR_LIST(HYBRID_ANDES_FIELD)
205	#undef HYBRID_ANDES_FIELD
206	
207	    // M-ext CSR block (v4): resolve by gdb mnemonic (NULL if the stub does not
208	    // advertise it for the paired cpu).
209	#define HYBRID_M_EXT_FIELD(field, addr, name) v->m_ext_##field = find_reg(regs, name);
210	    HYBRID_M_EXT_CSR_LIST(HYBRID_M_EXT_FIELD)
211	#undef HYBRID_M_EXT_FIELD
212	    for (int i = 0; i < HYBRID_PMA_CFG_NUM; i++) {
213	        // RV64 packs 8 PMA entries per cfg CSR, so only even cfg CSRs exist.
214	        g_snprintf(buf, sizeof(buf), "pmacfg%d", 2 * i);
215	        v->pmacfg[i] = find_reg(regs, buf);
216	    }
217	    for (int i = 0; i < HYBRID_PMA_ADDR_NUM; i++) {
218	        g_snprintf(buf, sizeof(buf), "pmaaddr%d", i);
219	        v->pmaaddr[i] = find_reg(regs, buf);
220	    }
221	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++) {
222	        g_snprintf(buf, sizeof(buf), "pmpcfg%d", i);
223	        v->pmpcfg[i] = find_reg(regs, buf);
224	    }
225	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++) {
226	        g_snprintf(buf, sizeof(buf), "pmpaddr%d", i);
227	        v->pmpaddr[i] = find_reg(regs, buf);
228	    }
229	
230	    v->vstart = find_reg(regs, "vstart");
231	    v->vxsat  = find_reg(regs, "vxsat");
232	    v->vxrm   = find_reg(regs, "vxrm");
233	    v->vcsr   = find_reg(regs, "vcsr");
234	    v->vtype  = find_reg(regs, "vtype");
235	    v->vl     = find_reg(regs, "vl");
236	    v->vlenb  = find_reg(regs, "vlenb");
237	    for (int i = 0; i < 32; i++) {
238	        g_snprintf(buf, sizeof(buf), "v%d", i);
239	        v->vreg[i] = find_reg(regs, buf);
240	    }
241	}
242	
243	static uint64_t read_reg64(struct qemu_plugin_register *h)
244	{
245	    if (!h) return 0;
246	    g_autoptr(GByteArray) buf = g_byte_array_new();
247	    int sz = qemu_plugin_read_register(h, buf);
248	    if (sz <= 0) return 0;
249	    uint64_t v = 0;
250	    memcpy(&v, buf->data, sz < 8 ? (size_t) sz : 8);
251	    return v;
252	}
253	
254	// Reads up to `dst_max` bytes from a register handle. Returns the byte
255	// count written (0 on failure or NULL handle). Used for vector regs whose
256	// width = vlenb bytes.
257	static size_t read_reg_bytes(struct qemu_plugin_register *h,
258	                             uint8_t *dst, size_t dst_max)
259	{
260	    if (!h || dst_max == 0) return 0;
261	    g_autoptr(GByteArray) buf = g_byte_array_new();
262	    int sz = qemu_plugin_read_register(h, buf);
263	    if (sz <= 0) return 0;
264	    size_t n = (size_t) sz < dst_max ? (size_t) sz : dst_max;
265	    memcpy(dst, buf->data, n);
266	    return n;
267	}
268	
269	// Atomic on POSIX: write to a mkstemp-reserved tmp file, fsync, rename.
270	// mkstemp guarantees uniqueness via a 6-char random suffix + atomic
271	// O_EXCL-style inode reservation, so concurrent plugin instances cannot
272	// collide even under aggressive PID reuse (B13). The tmp lives in the
273	// same directory as `path` so the rename is intra-filesystem.
274	static int write_blob_atomic(const void *data, size_t len, const char *path)
275	{
276	    char tmp[PATH_MAX];
277	    int n = g_snprintf(tmp, sizeof(tmp), "%s.tmp.XXXXXX", path);
278	    if (n < 0 || (size_t) n >= sizeof(tmp)) {
279	        fprintf(stderr, "hybrid_handoff: tmp path too long\n");
280	        return -1;
281	    }
282	    int fd = g_mkstemp(tmp);
283	    if (fd < 0) {
284	        perror("hybrid_handoff: g_mkstemp");
285	        return -1;
286	    }
287	    // g_mkstemp creates the file 0600; no further chmod needed.
288	    ssize_t got = write(fd, data, len);
289	    if (got != (ssize_t) len) {
290	        perror("hybrid_handoff: write");
291	        close(fd);
292	        unlink(tmp);
293	        return -1;
294	    }
295	    fsync(fd);
296	    close(fd);
297	    if (rename(tmp, path) != 0) {
298	        perror("hybrid_handoff: rename");
299	        unlink(tmp);
300	        return -1;
301	    }
302	    return 0;
303	}
304	
305	static int write_state_atomic(const struct hybrid_state_v1 *s, const char *path)
306	{
307	    return write_blob_atomic(s, sizeof(*s), path);
308	}
309	
310	// Drain CPU state into `*s`. pc is computed by the caller (from a
311	// HandoffSite for trigger paths). If minstret_override is non-zero, it
312	// replaces QEMU's PMU minstret.
313	static void drain_state_into(unsigned int vcpu_idx, uint64_t pc,
314	                             uint64_t minstret_override,
315	                             struct hybrid_state_v1 *sp)
316	{
317	    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
318	    resolve_handles(v);
319	    memset(sp, 0, sizeof(*sp));
320	    struct hybrid_state_v1 s = {0};
321	    s.magic   = HYBRID_STATE_MAGIC;
322	    s.version = HYBRID_STATE_VERSION;
323	    s.flags   = HYBRID_FLAG_RV64;
324	    s.hart_id = vcpu_idx;
325	    // L6: real privilege at the boundary; M-mode fallback only when the
326	    // stub doesn't advertise the gdbstub virtual feature (a missing handle
327	    // reads as 0 = U, which would silently demote the hart).
328	    s.priv    = v->priv ? (read_reg64(v->priv) & 0x3) : 3;
329	    s.pc      = pc;
330	    for (int i = 0; i < 32; i++) s.gpr[i] = read_reg64(v->gpr[i]);
331	
332	    // Floating-point: only set FP flag if at least one handle was bound,
333	    // i.e. QEMU advertised the FPU feature (D extension).
334	    int has_fp = 0;
335	    for (int i = 0; i < 32; i++) {
336	        s.fpr[i] = read_reg64(v->fpr[i]);
337	        if (v->fpr[i]) has_fp = 1;
338	    }
339	    if (has_fp) s.flags |= HYBRID_FLAG_FP;
340	    s.fcsr = read_reg64(v->fcsr);  // L20: rides HYBRID_FLAG_FP
341	
342	    s.mstatus  = read_reg64(v->mstatus);
343	    s.mepc     = read_reg64(v->mepc);
344	    s.mtvec    = read_reg64(v->mtvec);
345	    s.mcause   = read_reg64(v->mcause);
346	    s.mtval    = read_reg64(v->mtval);
347	    s.mscratch = read_reg64(v->mscratch);
348	    s.medeleg  = read_reg64(v->medeleg);
349	    s.mideleg  = read_reg64(v->mideleg);
350	    s.mip      = read_reg64(v->mip);
351	    s.mie      = read_reg64(v->mie);
352	    s.mcycle   = read_reg64(v->mcycle);
353	    s.minstret = minstret_override ? minstret_override
354	                                   : read_reg64(v->minstret);
355	    s.satp     = read_reg64(v->satp);
356	
357	    // Andes cache fix: carry crt0's cache-enable so the cycle engine resumes
358	    // with caches on (NULL handle on a non-Andes stub reads back as 0).
359	    s.mcache_ctl = read_reg64(v->mcache_ctl);
360	    s.mmisc_ctl  = read_reg64(v->mmisc_ctl);
361	
362	    // Andes V5 CSR block (v3): drain every transported Andes CSR. Set
363	    // HYBRID_FLAG_ANDES if the stub advertised at least one (mirrors has_fp/
364	    // has_v); otherwise the block stays zero and consumers skip it. A NULL
365	    // handle on a non-Andes stub reads back as 0 -> tolerant.
366	    int has_andes = 0;
367	#define HYBRID_ANDES_FIELD(field, addr, name)  \
368	    s.andes.field = read_reg64(v->andes_##field); \
369	    if (v->andes_##field) has_andes = 1;
370	    HYBRID_ANDES_CSR_LIST(HYBRID_ANDES_FIELD)
371	#undef HYBRID_ANDES_FIELD
372	    for (int i = 0; i < HYBRID_PMA_CFG_NUM; i++) {
373	        s.andes.pmacfg[i] = read_reg64(v->pmacfg[i]);
374	        if (v->pmacfg[i]) has_andes = 1;
375	    }
376	    for (int i = 0; i < HYBRID_PMA_ADDR_NUM; i++) {
377	        s.andes.pmaaddr[i] = read_reg64(v->pmaaddr[i]);
378	        if (v->pmaaddr[i]) has_andes = 1;
379	    }
380	    if (has_andes) s.flags |= HYBRID_FLAG_ANDES;
381	
382	    // M-ext CSR block (v4): drain every transported M-mode CSR the stub
383	    // advertised. Set HYBRID_FLAG_M_EXT if at least one resolved; a NULL handle
384	    // reads 0. The vsim caps gate decides which of these the cycle engine
385	    // actually restores, so draining an absent-on-vsim CSR here is harmless.
386	    int has_m_ext = 0;
387	#define HYBRID_M_EXT_FIELD(field, addr, name)  \
388	    s.m_ext.field = read_reg64(v->m_ext_##field); \
389	    if (v->m_ext_##field) has_m_ext = 1;
390	    HYBRID_M_EXT_CSR_LIST(HYBRID_M_EXT_FIELD)
391	#undef HYBRID_M_EXT_FIELD
392	    if (has_m_ext) s.flags |= HYBRID_FLAG_M_EXT;
393	
394	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++)
395	        s.pmpcfg[i] = read_reg64(v->pmpcfg[i]);
396	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++)
397	        s.pmpaddr[i] = read_reg64(v->pmpaddr[i]);
398	
399	    // Vector: only set V flag if QEMU advertised the V extension. vlenb
400	    // bounds the per-register byte count copied into vreg[]. The policy
401	    // helper (hybrid_v_drain_policy) decides SKIP/OK/ABORT from the
402	    // handle truthiness so we don't conflate "stub missing vlenb" with
403	    // "V disabled at runtime"; see include/hybrid/v_drain_policy.h.
404	    s.vstart = read_reg64(v->vstart);
405	    s.vxsat  = read_reg64(v->vxsat);
406	    s.vxrm   = read_reg64(v->vxrm);
407	    s.vcsr   = read_reg64(v->vcsr);
408	    s.vtype  = read_reg64(v->vtype);
409	    s.vl     = read_reg64(v->vl);
410	    s.vlenb  = read_reg64(v->vlenb);
411	    int has_other_v = (v->vstart || v->vxsat || v->vxrm || v->vcsr
412	                       || v->vtype || v->vl);
413	    if (!has_other_v) {
414	        for (int i = 0; i < 32; i++)
415	            if (v->vreg[i]) { has_other_v = 1; break; }
416	    }
417	    HybridVDrainPolicy vpol = hybrid_v_drain_policy(
418	        v->vlenb != NULL, has_other_v, s.vlenb);
419	    if (vpol == HYBRID_V_DRAIN_ABORT) {
420	        if (v->vlenb == NULL)
421	            fprintf(stderr,
422	                    "hybrid_handoff: stub advertised V CSRs/regs but not "
423	                    "vlenb; refusing to drain partial V state\n");
424	        else
425	            fprintf(stderr,
426	                    "hybrid_handoff: vlenb=%" PRIu64 " exceeds the wire-format "
427	                    "ceiling HYBRID_VLEN_BYTES_MAX=%d (VLEN %d); refusing to "
428	                    "truncate V registers\n",
429	                    s.vlenb, HYBRID_VLEN_BYTES_MAX,
430	                    8 * HYBRID_VLEN_BYTES_MAX);
431	        exit(2);
432	    }
433	    if (vpol == HYBRID_V_DRAIN_OK) {
434	        s.flags |= HYBRID_FLAG_V;
435	        /* The policy guarantees vlenb <= HYBRID_VLEN_BYTES_MAX here, so the
436	         * full live register fits the wire-format slot -- no clamp (L11). */
437	        for (int i = 0; i < 32; i++)
438	            (void) read_reg_bytes(v->vreg[i],
439	                                  &s.vreg[(size_t) i * HYBRID_VLEN_BYTES_MAX],
440	                                  (size_t) s.vlenb);
441	    }
442	
443	    // v6: which mask-governed CSRs the guest actually wrote (translate-time
444	    // decode + exec callbacks above). ucode rides transport-always: DSP
445	    // instructions update its sticky OV flag without any CSR instruction, so
446	    // instruction-level tracking cannot see those writes (like fcsr's fflags).
447	    s.write_mask[0] = __atomic_load_n(&csr_write_mask[0], __ATOMIC_RELAXED);
448	    s.write_mask[1] = __atomic_load_n(&csr_write_mask[1], __ATOMIC_RELAXED);
449	    hybrid_wm_set(s.write_mask, HYBRID_WM_ANDES_BASE + HYBRID_WM_ANDES_IDX_ucode);
450	    s.flags |= HYBRID_FLAG_WRITE_MASK;
451	
452	    // v5: L2C MMIO register window (DS220 11.8.5 Table 112, offsets
453	    // 0x0000..0x0527). Read the whole documented block from the L2C base by
454	    // PHYSICAL address (paging is off in the M-mode boot flow, so VA==PA anyway).
455	    // QEMU's AE350 machine maps L2C as a device region; if the read fails (a
456	    // machine without an L2C), the flag stays clear and consumers skip the
457	    // block. Little-endian native host, so the raw bytes land directly in
458	    // s.l2c.reg[]. The vsim side gates restore on its OWN L2C presence, so
459	    // setting the flag whenever QEMU can read the region is correct.
460	    {
461	        g_autoptr(GByteArray) l2c = g_byte_array_new();
462	        enum qemu_plugin_hwaddr_operation_result r =
463	            qemu_plugin_read_memory_hwaddr(l2c_base_arg, l2c,
464	                                           HYBRID_L2C_REG_WINDOW_BYTES);
465	        if (r == QEMU_PLUGIN_HWADDR_OPERATION_OK
466	            && l2c->len == HYBRID_L2C_REG_WINDOW_BYTES) {
467	            memcpy(s.l2c.reg, l2c->data, HYBRID_L2C_REG_WINDOW_BYTES);
468	            s.flags |= HYBRID_FLAG_L2C;
469	        }
470	    }
471	
472	    *sp = s;
473	}
474	
475	// LM sidecar drain: read `size` bytes of local memory at physical `base`
476	// (the slave-port aperture) into "<state_path><suffix>". Failure is as hard
477	// an error as a failed state write: the caller asked for this memory
478	// (size > 0), so a missing/short sidecar must not masquerade as a clean
479	// handoff -- the vsim leg would silently resume with an empty ILM/DLM,
480	// exactly the bug this transport exists to fix.
481	static void drain_lm_sidecar(const char *state_path, const char *suffix,
482	                             uint64_t base, uint64_t size)
483	{
484	    if (size == 0) return;
485	    g_autofree char *path = g_strdup_printf("%s%s", state_path, suffix);
486	    g_autoptr(GByteArray) buf = g_byte_array_new();
487	    enum qemu_plugin_hwaddr_operation_result r =
488	        qemu_plugin_read_memory_hwaddr(base, buf, size);
489	    if (r != QEMU_PLUGIN_HWADDR_OPERATION_OK || buf->len != size) {
490	        fprintf(stderr,
491	                "hybrid_handoff: cannot read %" PRIu64 " bytes of local "
492	                "memory at %#" PRIx64 " (result %d)\n", size, base, (int) r);
493	        exit(2);
494	    }
495	    if (write_blob_atomic(buf->data, buf->len, path) != 0) {
496	        fprintf(stderr, "hybrid_handoff: failed to write %s\n", path);
497	        exit(2);
498	    }
499	}
500	
501	// Drain CPU state to `path`. Does NOT call exit -- the caller decides
502	// exit(200).
503	static void drain_state_to_file(unsigned int vcpu_idx, uint64_t pc,
504	                                uint64_t minstret_override, const char *path)
505	{
506	    struct hybrid_state_v1 s;
507	    drain_state_into(vcpu_idx, pc, minstret_override, &s);
508	    if (write_state_atomic(&s, path) != 0) {
509	        fprintf(stderr, "hybrid_handoff: failed to write state file\n");
510	        exit(2);
511	    }
512	    // LM transport (F1) + HVM transport (F2): content sidecars ride next to
513	    // the state file; this is the single choke point, so every trigger mode
514	    // (marker/pc/oracle) gets them.
515	    drain_lm_sidecar(path, ".ilm", ilm_base_arg, ilm_size_arg);
516	    drain_lm_sidecar(path, ".dlm", dlm_base_arg, dlm_size_arg);
517	    drain_lm_sidecar(path, ".hvm", hvm_base_arg, hvm_size_arg);
518	    fprintf(stderr,
519	            "hybrid_handoff: drained state to %s (pc=%#" PRIx64 ")\n",
520	            path, s.pc);
521	}
522	
523	// Shared drain tail: capture the (pre-execution) state, report `resume_pc`
524	// as the vsim resume point, and exit 200.
525	static void handoff_drain(unsigned int vcpu_idx, uint64_t resume_pc)
526	{
527	    drain_state_to_file(vcpu_idx, resume_pc, 0, outfile_path);
528	    // 200 == kExitHandoffToQemu in verilator/src/hybrid/exit_codes.hpp.
529	    // Distinguishes drain from workload completion (0) so the orchestrator
530	    // can decide the next spawn.
531	    exit(200);
532	}
533	
534	// Marker sites. The marker is an architectural NOP, so the pre-execution
535	// state equals the post-retire state and the window resumes AFTER it
536	// (vaddr+size, computed at translation time; reading the gdbstub PC inside
537	// the exec callback can lag the actual current insn when V instructions
538	// retire just before the trigger -- TCG defers PC writes for performance).
539	static void on_handoff(unsigned int vcpu_idx, void *udata)
540	{
541	    const HandoffSite *site = (const HandoffSite *) udata;
542	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
543	    handoff_drain(vcpu_idx, compute_handoff_pc(site));
544	}
545	
546	// pc boundary sites. Exec callbacks fire BEFORE the insn
547	// executes, and the boundary insn is real user code (unlike a marker NOP):
548	// the drained state must resume AT the boundary so the insn executes inside
549	// the vsim window rather than on neither leg. (Skipping it corrupts the
550	// window's architectural state -- e.g. a skipped vsetivli leaves vtype.vill
551	// set and the first vector op of the window faults.)
552	static void on_handoff_boundary(unsigned int vcpu_idx, void *udata)
553	{
554	    const HandoffSite *site = (const HandoffSite *) udata;
555	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
556	    handoff_drain(vcpu_idx, site->vaddr);
557	}
558	
559	// Per-insn tick for oracle exit-drain mode. udata is this insn's HandoffSite.
560	// When armed (the exit boundary's own tick ran), this tick fires before its
561	// insn executes, so a drain here records the post-retire state of the
562	// boundary insn with pc = the dynamically-next insn's vaddr.
563	static void on_oracle_tick(unsigned int vcpu_idx, void *udata)
564	{
565	    const HandoffSite *site = (const HandoffSite *) udata;
566	    if (oracle_armed
567	        && (!drain_pc_set || site->vaddr == drain_pc_arg)) {
568	        handoff_drain(vcpu_idx, site->vaddr);
569	    }
570	    if (exit_pc_mode ? (site->vaddr == exit_pc_arg)
571	                     : (site->kind == HYBRID_HANDOFF_EXIT)) {
572	        oracle_armed = 1;
573	    }
574	}
575	
576	static void vcpu_tb_trans(qemu_plugin_id_t id, struct qemu_plugin_tb *tb)
577	{
578	    (void) id;
579	    size_t n = qemu_plugin_tb_n_insns(tb);
580	
581	    for (size_t i = 0; i < n; i++) {
582	        struct qemu_plugin_insn *insn = qemu_plugin_tb_get_insn(tb, i);
583	
584	        // v6: CSR write-mask tracking, active in every trigger mode (the mode
585	        // branches below `continue`). Decoded once at translation; only an
586	        // instruction that writes a mask-governed CSR gets an exec callback
587	        // (the CSR address is a static field of the encoding), so this costs
588	        // nothing at execution time outside boot-style CSR setup code. No
589	        // compressed CSR instruction exists, so the size==4 gate is exact.
590	        if (qemu_plugin_insn_size(insn) == 4) {
591	            uint32_t w = 0;
592	            if (qemu_plugin_insn_data(insn, &w, sizeof(w)) == sizeof(w)) {
593	                const int slot = hybrid_wm_slot_for_insn(w);
594	                if (slot >= 0)
595	                    qemu_plugin_register_vcpu_insn_exec_cb(
596	                        insn, on_csr_write, QEMU_PLUGIN_CB_NO_REGS,
597	                        (void *) (uintptr_t) slot);
598	            }
599	        }
600	
601	        // Oracle exit-drain mode: exclusive with every other mode (enforced
602	        // at install), so it owns the insn's registration outright. The site
603	        // carries the marker kind so the tick can arm on the EXIT marker.
604	        if (exit_marker_mode || exit_pc_mode) {
605	            HandoffSite *site = g_new0(HandoffSite, 1);
606	            site->kind  = HYBRID_HANDOFF_NONE;
607	            site->vaddr = qemu_plugin_insn_vaddr(insn);
608	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
609	            if (exit_marker_mode && site->size == 4) {
610	                uint32_t raw = 0;
611	                if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) == sizeof(raw))
612	                    hybrid_match_handoff_insn(raw, &site->kind);
613	            }
614	            qemu_plugin_register_vcpu_insn_exec_cb(
615	                insn, on_oracle_tick, QEMU_PLUGIN_CB_R_REGS, site);
616	            continue;
617	        }
618	
619	        if (pc_mode) {
620	            // PC-trigger mode: vaddr-only match; the drain resumes AT the
621	            // boundary (on_handoff_boundary), so the insn size is recorded
622	            // only for completeness.
623	            if (qemu_plugin_insn_vaddr(insn) != enter_pc_arg) continue;
624	            HandoffSite *site = g_new0(HandoffSite, 1);
625	            site->kind  = HYBRID_HANDOFF_ENTER;
626	            site->vaddr = qemu_plugin_insn_vaddr(insn);
627	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
628	            qemu_plugin_register_vcpu_insn_exec_cb(
629	                insn, on_handoff_boundary, QEMU_PLUGIN_CB_R_REGS, site);
630	            continue;
631	        }
632	
633	        // Marker-trigger mode (default).
634	        // The markers are `slti x0, x0, 0x5A0/0x5A1`, always 32-bit
635	        // (sz==4): SLTI has no compressed form, so the sz!=4 skip is
636	        // exact, not an approximation.
637	        size_t sz = qemu_plugin_insn_size(insn);
638	        if (sz != 4) continue;
639	        uint32_t raw = 0;
640	        if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) != sizeof(raw))
641	            continue;
642	        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
643	        if (!hybrid_match_handoff_insn(raw, &kind)) continue;
644	        HandoffSite *site = g_new0(HandoffSite, 1);
645	        site->kind  = kind;
646	        site->vaddr = qemu_plugin_insn_vaddr(insn);
647	        site->size  = (uint32_t) sz;
648	        qemu_plugin_register_vcpu_insn_exec_cb(
649	            insn, on_handoff, QEMU_PLUGIN_CB_R_REGS, site);
650	    }
651	}
652	
653	// Parse a `name=value` plugin arg's value as u64 (base auto-detected, so
654	// 0x-hex and decimal both work). Same accept/reject behavior as the previous
655	// per-option copies of this block. Returns 0 on success, -1 (after printing
656	// the standard invalid-arg line) on garbage.
657	static int parse_u64_arg(const char *name, const char *val, uint64_t *out)
658	{
659	    char *endp = NULL;
660	    unsigned long long v = g_ascii_strtoull(val, &endp, 0);
661	    if (!endp || *endp != '\0') {
662	        fprintf(stderr, "hybrid_handoff: invalid %s=%s\n", name, val);
663	        return -1;
664	    }
665	    *out = (uint64_t) v;
666	    return 0;
667	}
668	
669	QEMU_PLUGIN_EXPORT int qemu_plugin_install(qemu_plugin_id_t id,
670	                                           const qemu_info_t *info,
671	                                           int argc, char **argv)
672	{
673	    (void) info;
674	    for (int i = 0; i < argc; i++) {
675	        g_auto(GStrv) tok = g_strsplit(argv[i], "=", 2);
676	        if (g_strcmp0(tok[0], "outfile") == 0 && tok[1]) {
677	            outfile_path = g_strdup(tok[1]);
678	        } else if (g_strcmp0(tok[0], "enter_pc") == 0 && tok[1]) {
679	            if (parse_u64_arg("enter_pc", tok[1], &enter_pc_arg) != 0)
680	                return -1;
681	            pc_mode = 1;
682	        } else if (g_strcmp0(tok[0], "exit_pc") == 0 && tok[1]) {
683	            if (parse_u64_arg("exit_pc", tok[1], &exit_pc_arg) != 0)
684	                return -1;
685	            exit_pc_mode = 1;
686	        } else if (g_strcmp0(tok[0], "exit_marker") == 0 && tok[1]) {
687	            uint64_t v;
688	            if (parse_u64_arg("exit_marker", tok[1], &v) != 0)
689	                return -1;
690	            exit_marker_mode = (v != 0);
691	        } else if (g_strcmp0(tok[0], "drain_pc") == 0 && tok[1]) {
692	            if (parse_u64_arg("drain_pc", tok[1], &drain_pc_arg) != 0)
693	                return -1;
694	            drain_pc_set = 1;
695	        } else if (g_strcmp0(tok[0], "l2c_base") == 0 && tok[1]) {
696	            if (parse_u64_arg("l2c_base", tok[1], &l2c_base_arg) != 0)
697	                return -1;
698	        } else if (g_strcmp0(tok[0], "ilm_base") == 0 && tok[1]) {
699	            if (parse_u64_arg("ilm_base", tok[1], &ilm_base_arg) != 0)
700	                return -1;
701	        } else if (g_strcmp0(tok[0], "ilm_size") == 0 && tok[1]) {
702	            if (parse_u64_arg("ilm_size", tok[1], &ilm_size_arg) != 0)
703	                return -1;
704	        } else if (g_strcmp0(tok[0], "dlm_base") == 0 && tok[1]) {
705	            if (parse_u64_arg("dlm_base", tok[1], &dlm_base_arg) != 0)
706	                return -1;
707	        } else if (g_strcmp0(tok[0], "dlm_size") == 0 && tok[1]) {
708	            if (parse_u64_arg("dlm_size", tok[1], &dlm_size_arg) != 0)
709	                return -1;
710	        } else if (g_strcmp0(tok[0], "hvm_base") == 0 && tok[1]) {
711	            if (parse_u64_arg("hvm_base", tok[1], &hvm_base_arg) != 0)
712	                return -1;
713	        } else if (g_strcmp0(tok[0], "hvm_size") == 0 && tok[1]) {
714	            if (parse_u64_arg("hvm_size", tok[1], &hvm_size_arg) != 0)
715	                return -1;
716	        } else {
717	            fprintf(stderr, "hybrid_handoff: unknown option: %s\n", argv[i]);
718	            return -1;
719	        }
720	    }
721	    if (!outfile_path) {
722	        fputs("hybrid_handoff: outfile=PATH is required\n", stderr);
723	        return -1;
724	    }
725	    if (pc_mode) {
726	        fprintf(stderr,
727	                "hybrid_handoff: PC-mode enter=0x%" PRIx64 "\n",
728	                enter_pc_arg);
729	    }
730	    if (exit_marker_mode || exit_pc_mode) {
731	        if ((exit_marker_mode && exit_pc_mode) || pc_mode) {
732	            fputs("hybrid_handoff: oracle exit drain (exit_marker/exit_pc) "
733	                  "is exclusive with the other trigger modes\n", stderr);
734	            return -1;
735	        }
736	        if (exit_pc_mode) {
737	            fprintf(stderr,
738	                    "hybrid_handoff: oracle exit-drain mode exit_pc=0x%"
739	                    PRIx64 "\n", exit_pc_arg);
740	        } else {
741	            fputs("hybrid_handoff: oracle exit-drain mode (exit marker)\n",
742	                  stderr);
743	        }
744	        if (drain_pc_set) {
745	            fprintf(stderr, "hybrid_handoff: oracle drain_pc=0x%" PRIx64 "\n",
746	                    drain_pc_arg);
747	        }
748	    } else if (drain_pc_set) {
