1	/* Trap glue shared by all C-level round-trip fixtures.
2	 *
3	 * crt0.S invokes init_mtvec() as a constructor; trap.S's m_trap_entry
4	 * tail-calls handle_trap on every exception or interrupt. libgloss_vh
5	 * routes syscalls through the RISC-V semihosting magic triple, not
6	 * through `ecall`, so there's no syscall-dispatch table here. Any trap
7	 * is treated as a fatal error: print a diagnostic and exit.
8	 */
9	
10	#ifdef __cplusplus
11	extern "C"
12	{
13	#endif
14	
15	#include <stdint.h>
16	#include <stdio.h>
17	
18	#define WRITE_ERROR(format, ...) \
19	  fprintf(stderr, "\033[31m[ERROR] " format "\033[0m\n", ##__VA_ARGS__)
20	
21	__attribute__((used, noreturn)) void _exit(int exit_status);
22	
23	void exception_handler(void)
24	{
25	  /* XLEN-wide so rv64 mepc/mtval are not truncated and the format is warning-
26	   * free on both ABIs (unsigned long is 32-bit on ilp32, 64-bit on lp64). */
27	  unsigned long mcause, mdcause, mepc, mtval;
28	
29	  asm volatile("csrr %0, mcause" : "=r"(mcause));
30	  asm volatile("csrr %0, mdcause" : "=r"(mdcause));
31	  asm volatile("csrr %0, mepc" : "=r"(mepc));
32	  asm volatile("csrr %0, mtval" : "=r"(mtval));
33	
34	  const unsigned long intbit = 1UL << (__riscv_xlen - 1);  /* mcause MSB */
35	
36	  WRITE_ERROR("Trap occurred!");
37	  WRITE_ERROR("mcause: 0x%lx", mcause);
38	  WRITE_ERROR("mdcause: 0x%lx", mdcause);
39	  WRITE_ERROR("mepc: 0x%lx", mepc);
40	  WRITE_ERROR("mtval: 0x%lx", mtval);
41	
42	  if ((mcause & intbit) == 0) {
43	    WRITE_ERROR("Exception code: %lu", mcause);
